using UnityEngine;

namespace Universes.UniverseData.hide_and_seek {
    /// <summary>
    /// The hinged door of a walk-in hiding spot (a closet, a locker, the outhouse). It sits on the hinge;
    /// the leaf and its collider are children, so a closed door blocks sight, tags and flashlight beams.
    /// Lives in hide_and_seek_start, so the server and every client have the same doors: the server
    /// decides who may open or close one (<see cref="HS_Doors"/>) and snaps it, clients swing it.
    /// Generated by the manor builder; every field is filled there.
    /// </summary>
    public sealed class HS_HideDoor : MonoBehaviour {
        [Tooltip("The spot's name for prompts and the results list (\"Coat Closet\").")]
        public string spotName;
        [Tooltip("Local yaw of the hinge when the door is shut and when it stands open.")]
        public float closedYaw, openYaw;
        [Tooltip("World-space inside of the spot: a hider standing in it is behind this door.")]
        public Bounds interior;
        [Tooltip("World-space ends of the shut leaf at floor height (hinge end first): reach and the doorway check measure from this line.")]
        public Vector3 closedFrom, closedTo;
        [Tooltip("Seconds a client takes to swing the door (the server snaps it at once).")]
        [Min(0f)] public float swingSeconds = 0.3f;

        bool open = true;
        float swingFrom, swingTo, swingStartedAt = -1f;

        public bool IsOpen => open;

        /// <summary>The middle of the shut leaf at floor height.</summary>
        public Vector3 Centre => (closedFrom + closedTo) * 0.5f;

        /// <summary>Whether <paramref name="position"/> (a character's feet) is inside the spot.</summary>
        public bool Contains(Vector3 position) => interior.Contains(position + Vector3.up * 0.5f);

        /// <summary>
        /// Opens or shuts the door. <paramref name="animate"/> swings it (clients); otherwise it snaps and its
        /// collider moves at once (the server, and a client catching up on a late state).
        /// </summary>
        public void SetOpen(bool value, bool animate) {
            if (open == value && swingStartedAt < 0f) {
                SetYaw(value ? openYaw : closedYaw);
                return;
            }
            open = value;
            float target = value ? openYaw : closedYaw;
            if (!animate || swingSeconds <= 0f) {
                swingStartedAt = -1f;
                SetYaw(target);
                Physics.SyncTransforms();
                return;
            }
            swingFrom = transform.localEulerAngles.y;
            swingTo = target;
            swingStartedAt = Time.time;
        }

        void Update() {
            if (swingStartedAt < 0f) return;
            float t = Mathf.Clamp01((Time.time - swingStartedAt) / swingSeconds);
            // Ease out: the door is flung, then slows against its stop.
            float eased = 1f - (1f - t) * (1f - t) * (1f - t);
            SetYaw(Mathf.LerpAngle(swingFrom, swingTo, eased));
            if (t >= 1f) swingStartedAt = -1f;
        }

        void SetYaw(float yaw) => transform.localRotation = Quaternion.Euler(0f, yaw, 0f);

        void OnDrawGizmosSelected() {
            Gizmos.color = new Color(0.3f, 0.9f, 0.4f, 0.6f);
            Gizmos.DrawWireCube(interior.center, interior.size);
            Gizmos.color = Color.yellow;
            Gizmos.DrawLine(closedFrom, closedTo);
        }
    }
}
